action.command:
node -e "
const fs = require('fs');
const path = require('path');

const chunks = [];

process.stdin.on('data', d => chunks.push(d));

process.stdin.on('end', () => {
  try {
    const input = JSON.parse(Buffer.concat(chunks).toString());
    const prompt = String(input.userPrompt || '').toLowerCase();

    const configPath = path.join(process.cwd(), '.kiro', 'agents', 'agentspicker.json');
    const configFile = fs.readFileSync(configPath, 'utf8');
    const config = JSON.parse(configFile);

    const agents = config.agents || {};
    const priority = (config.routing && config.routing.priority) || [];

    const candidates = [];

    for (const [key, agent] of Object.entries(agents)) {
      const keywords = Array.isArray(agent.keywords) ? agent.keywords : [];
      const matches = keywords.filter(keyword => {
        const normalizedKeyword = String(keyword).toLowerCase().trim();
        return normalizedKeyword.length > 0 && prompt.includes(normalizedKeyword);
      });

      if (matches.length > 0) {
        const priorityIndex = priority.indexOf(agent.category);
        const effectivePriority = priorityIndex === -1 ? Number.MAX_SAFE_INTEGER : priorityIndex + 1;
        candidates.push({
          key,
          category: agent.category,
          agent: agent.name,
          model: agent.model,
          priority: effectivePriority,
          matches
        });
      }
    }

    const header  = '╔══════════════════════════════════════════════════════════════════════════════════╗';
    const title   = '║                             TRAVEL PLATFORM ROUTER                               ║';
    const divider = '╠══════════════════════════════════════════════════════════════════════════════════╣';
    const footer  = '╚══════════════════════════════════════════════════════════════════════════════════╝';

    function formatLine(label, value) {
      const left = ('║ ' + label).padEnd(21) + ': ';
      let valStr = String(value || '');
      if (valStr.length > 58) valStr = valStr.slice(0, 55) + '...';
      return left + valStr.padEnd(58) + '║';
    }

    if (candidates.length === 0) {
      process.stdout.write('\n' + header + '\n' + title + '\n' + divider + '\n' +
        formatLine('Project', 'TravelPlatform') + '\n' +
        formatLine('Lifecycle', 'SDLC') + '\n' +
        formatLine('Detected Phase', 'NONE') + '\n' +
        formatLine('Routing Category', 'NONE') + '\n' +
        formatLine('Selected Agent', 'NONE') + '\n' +
        formatLine('Selected Model', 'NONE') + '\n' +
        formatLine('Reason', 'No matching context signatures found') + '\n' +
        formatLine('Confidence', 'LOW') + '\n' + footer + '\n\n');
      return process.exit(0);
    }

    candidates.sort((a, b) => {
      if (a.priority !== b.priority) return a.priority - b.priority;
      return b.matches.length - a.matches.length;
    });

    const selected = candidates[0];
    const confidence = candidates.length === 1 && selected.matches.length >= 2 ? 'HIGH' : 'MEDIUM';
    const reasonText = selected.category === 'DEBUGGING' ? 'Failing test with 500 error investigation' : 'Context matched signature';

    process.stdout.write('\n' + header + '\n' + title + '\n' + divider + '\n' +
      formatLine('Project', 'TravelPlatform') + '\n' +
      formatLine('Lifecycle', 'SDLC') + '\n' +
      formatLine('Detected Phase', selected.category) + '\n' +
      formatLine('Routing Category', selected.category) + '\n' +
      formatLine('Selected Agent', selected.agent) + '\n' +
      formatLine('Selected Model', selected.model) + '\n' +
      formatLine('Reason', reasonText) + '\n' +
      formatLine('Confidence', confidence) + '\n' + footer + '\n' +
      'Delegating to ' + selected.agent + '...\n\n');

    process.exit(0);
  } catch (error) {
    process.exit(0);
  }
});
"
